  function isMarketPanelElement(element) {
    return element instanceof Element && Boolean(element.closest(marketPanelSelector));
  }

  function isDisplayOnlyItemName(element) {
    return element instanceof Element && Boolean(element.closest(displayOnlyItemNameSelector));
  }

  function addDisplayOnlyItemTranslation(element) {
    if (!(element instanceof Element) || !element.matches(displayOnlyItemNameSelector)) return;
    const label = element.querySelector(":scope > .normalItem");
    if (!label) return;
    const englishName = label.textContent?.trim();
    if (!englishName || englishName.includes("{{") || label.dataset.zhDisplayEnglish === englishName) return;
    const chineseName = translateDisplayOnlyItemName(englishName);
    if (!chineseName || chineseName === englishName) {
      delete label.dataset.zhDisplayOnly;
      delete label.dataset.zhLabel;
      delete label.dataset.zhDisplayEnglish;
      return;
    }
    label.dataset.zhDisplayOnly = "true";
    label.dataset.zhDisplayEnglish = englishName;
    label.dataset.zhLabel = chineseName;
    label.style.setProperty("--zh-item-label-size", `${getDisplayOnlyItemLabelSize(label, chineseName)}px`);
  }

  function getDisplayOnlyItemLabelSize(label, chineseName) {
    if (label.closest(".inventoryCards")) return 16;
    const computedStyle = window.getComputedStyle(label);
    const fontFamily = computedStyle.fontFamily || "sans-serif";
    const fontWeight = computedStyle.fontWeight || "normal";
    const canvas = document.createElement("canvas");
    const context = canvas.getContext("2d");
    if (!context) return 11;

    for (let size = 19; size >= 10; size -= 0.5) {
      context.font = `${fontWeight} ${size}px ${fontFamily}`;
      if (context.measureText(chineseName).width <= 257) return size;
    }
    return 10;
  }

  function translateDisplayOnlyItemName(englishName) {
    const directTranslation = getDisplayOnlyItemTranslation(englishName) || translateString(englishName);
    if (directTranslation !== englishName) return directTranslation;

    const primeMatch = englishName.match(/^(.*) Prime$/);
    if (primeMatch) {
      const baseTranslation = getDisplayOnlyItemTranslation(primeMatch[1]) || translations[primeMatch[1]];
      if (baseTranslation) return `${baseTranslation} Prime`;
    }

    const part = Object.keys(compoundPartTranslations).find(candidate => englishName.endsWith(` ${candidate}`));
    if (!part) return englishName;
    const itemName = englishName.slice(0, -(part.length + 1));
    const primeMatchWithPart = itemName.match(/^(.*) Prime$/);
    const baseName = primeMatchWithPart ? primeMatchWithPart[1] : itemName;
    const baseTranslation = getDisplayOnlyItemTranslation(baseName) || translations[baseName];
    const displayBaseName = baseTranslation || baseName;
    return `${displayBaseName}${primeMatchWithPart ? " Prime" : ""} ${compoundPartTranslations[part]}`;
  }

  function getDisplayOnlyItemTranslation(englishName) {
    return displayOnlyItemTranslations[englishName] || displayOnlyItemTranslationsByLowerCase[englishName.toLowerCase()];
  }

  function addDisplayOnlyItemTranslations(root) {
    if (!(root instanceof Element) && root?.nodeType !== Node.DOCUMENT_NODE && root?.nodeType !== Node.DOCUMENT_FRAGMENT_NODE) return;
    if (root instanceof Element) {
      const itemName = root.closest(displayOnlyItemNameSelector);
      if (itemName) addDisplayOnlyItemTranslation(itemName);
    }
    if (root instanceof Element && root.matches(displayOnlyItemNameSelector)) addDisplayOnlyItemTranslation(root);
    for (const element of root.querySelectorAll?.(displayOnlyItemNameSelector) ?? []) addDisplayOnlyItemTranslation(element);
  }

  function getEnglishInventorySearchTerm(searchTerm) {
    const normalizedSearch = searchTerm.trim().toLowerCase();
    if (!normalizedSearch || !/[\u3400-\u9fff]/.test(normalizedSearch)) return searchTerm;

    const directMatch = findExactEnglishItemName(normalizedSearch);
    if (directMatch) return directMatch;

    const compoundMatch = getEnglishCompoundItemSearchTerm(normalizedSearch);
    if (compoundMatch) return compoundMatch;

    const matchingNames = Object.entries(displayOnlyItemTranslations)
      .filter(([, chineseName]) => chineseName.toLowerCase().includes(normalizedSearch))
      .map(([englishName]) => englishName)
      .sort((left, right) => left.length - right.length);
    if (matchingNames.length === 1) return matchingNames[0];

    const sharedBaseName = matchingNames[0];
    return sharedBaseName && matchingNames.every(name => name.startsWith(sharedBaseName))
      ? sharedBaseName
      : searchTerm;
  }

  function hasChineseCharacters(value) {
    return /[\u3400-\u9fff]/.test(value);
  }

  function getChineseSearchableItemName(englishName) {
    return translateDisplayOnlyItemName(englishName).toLowerCase();
  }

  function filterInventoryItemsByChineseSearch(items, searchTerm) {
    const terms = searchTerm
      .toLowerCase()
      .trim()
      .split(/\s+/)
      .filter(Boolean);
    if (!terms.length) return items;

    return items.filter(item => {
      const englishName = item?.name || "";
      const searchableName = `${getChineseSearchableItemName(englishName)} ${englishName.toLowerCase()}`;
      return terms.every(term => searchableName.includes(term));
    });
  }

  function getChineseSearchTerms(searchTerm) {
    return searchTerm
      .toLowerCase()
      .trim()
      .split(/\s+/)
      .filter(Boolean);
  }

  function itemMatchesChineseSearch(item, searchTerm, nameFields) {
    const terms = getChineseSearchTerms(searchTerm);
    if (!terms.length) return true;

    const searchableNames = nameFields
      .map(field => item?.[field])
      .filter(value => typeof value === "string" && value)
      .map(englishName => `${getChineseSearchableItemName(englishName)} ${englishName.toLowerCase()}`)
      .join(" ");
    return terms.every(term => searchableNames.includes(term));
  }

  function filterNamedItemsByChineseSearch(items, searchTerm, nameFields) {
    if (!Array.isArray(items)) return items;
    return items.filter(item => itemMatchesChineseSearch(item, searchTerm, nameFields));
  }

  function findExactEnglishItemName(chineseName) {
    const itemMatch = Object.entries(displayOnlyItemTranslations)
      .filter(([, translatedName]) => translatedName.toLowerCase() === chineseName)
      .map(([englishName]) => englishName)
      .sort((left, right) => left.length - right.length)[0];
    if (itemMatch) return itemMatch;

    return Object.entries(translations)
      .filter(([, translatedName]) => translatedName.toLowerCase() === chineseName)
      .map(([englishName]) => englishName)
      .sort((left, right) => left.length - right.length)[0];
  }

  function getEnglishCompoundItemSearchTerm(chineseName) {
    const part = Object.entries(compoundPartTranslations)
      .sort(([, left], [, right]) => right.length - left.length)
      .find(([, translatedPart]) => chineseName.endsWith(` ${translatedPart.toLowerCase()}`));
    if (part) {
      const [englishPart, translatedPart] = part;
      const itemName = chineseName.slice(0, -(translatedPart.length + 1));
      const englishItemName = getEnglishPrimeItemSearchTerm(itemName) || findExactEnglishItemName(itemName);
      return englishItemName ? `${englishItemName} ${englishPart}` : null;
    }

    return getEnglishPrimeItemSearchTerm(chineseName);
  }

  function getEnglishPrimeItemSearchTerm(chineseName) {
    if (!chineseName.endsWith(" prime")) return null;
    const baseName = chineseName.slice(0, -6);
    const englishBaseName = findExactEnglishItemName(baseName);
    return englishBaseName ? `${englishBaseName} Prime` : null;
  }

  function enableChineseInventorySearch() {
    const inventoryApp = window.inventoryApp;
    const inventoryPlugin = window.plugin?.get?.();
    if (!inventoryApp?.refresh || !inventoryPlugin?.getFilteredInventory || inventoryApp.__zhChineseSearchEnabled) return;

    // 3.x reads search from Vue instead of #inventorySearch. Wrap the request
    // boundary so both interfaces keep their original query and request ids.
    const originalGetFilteredInventory = inventoryPlugin.getFilteredInventory.bind(inventoryPlugin);
    inventoryPlugin.getFilteredInventory = function (filterSettings, fullInventory, callback) {
      const filters = JSON.parse(filterSettings);
      const searchTerm = filters.search || "";
      if (!hasChineseCharacters(searchTerm)) return originalGetFilteredInventory(filterSettings, fullInventory, callback);
      filters.search = "";
      return originalGetFilteredInventory(JSON.stringify(filters), true, (success, data, ducatCount, platCount) => {
        if (!success) return callback(success, data, ducatCount, platCount);
        try {
          const filteredItems = filterInventoryItemsByChineseSearch(JSON.parse(data), searchTerm);
          // Native totals describe the unfiltered response. Do not present
          // those totals as if they belonged to the Chinese search result.
          return callback(true, JSON.stringify(filteredItems), null, null);
        } catch (error) {
          console.warn("[AlecaFrame-ZH] Inventory Chinese search failed", error);
          return callback(success, data, ducatCount, platCount);
        }
      });
    };
    inventoryApp.__zhChineseSearchEnabled = true;
  }

  function waitForChineseInventorySearch(attempt = 0) {
    enableChineseInventorySearch();
    if (!window.inventoryApp?.__zhChineseSearchEnabled && attempt < 40) {
      setTimeout(() => waitForChineseInventorySearch(attempt + 1), 250);
    }
  }

  function enableChineseFoundrySearch() {
    const foundryApp = window.foundryApp;
    const foundryPlugin = window.plugin?.get?.();
    if (!foundryApp?.refresh || !foundryPlugin?.getFilteredFoundry || foundryApp.__zhChineseSearchEnabled) return;

    const originalGetFilteredFoundry = foundryPlugin.getFilteredFoundry.bind(foundryPlugin);
    foundryPlugin.getFilteredFoundry = function (filterSettings, fullInventory, callback) {
      const filters = JSON.parse(filterSettings);
      const searchTerm = filters.search || "";
      if (!hasChineseCharacters(searchTerm)) {
        return originalGetFilteredFoundry(filterSettings, fullInventory, callback);
      }

      // The native plugin only searches English. Fetch the current category
      // without a search term, then filter its results by Chinese or English name.
      filters.search = "";
      return originalGetFilteredFoundry(JSON.stringify(filters), fullInventory, (success, data) => {
        if (!success) return callback(success, data);
        try {
          const filteredItems = filterNamedItemsByChineseSearch(JSON.parse(data), searchTerm, ["name"]);
          return callback(true, JSON.stringify(filteredItems));
        } catch (error) {
          console.warn("[AlecaFrame-ZH] Foundry Chinese search failed", error);
          return callback(success, data);
        }
      });
    };
    foundryApp.__zhChineseSearchEnabled = true;
  }

  function waitForChineseFoundrySearch(attempt = 0) {
    enableChineseFoundrySearch();
    if (!window.foundryApp?.__zhChineseSearchEnabled && attempt < 40) {
      setTimeout(() => waitForChineseFoundrySearch(attempt + 1), 250);
    }
  }

  function enableChineseWfmListSearch(appName, pluginMethodName, nameFields) {
    const app = window[appName];
    const marketPlugin = window.plugin?.get?.();
    if (!app?.refresh || !marketPlugin?.[pluginMethodName] || app.__zhChineseSearchEnabled) return;

    const originalRefresh = app.refresh.bind(app);
    const originalPluginMethod = marketPlugin[pluginMethodName].bind(marketPlugin);
    app.refresh = function (...args) {
      const originalSearch = this.selectedSearch || "";
      if (!hasChineseCharacters(originalSearch)) return originalRefresh(...args);

      marketPlugin[pluginMethodName] = function (filterSettings, callback) {
        const filters = JSON.parse(filterSettings);
        filters.search = "";
        const wrappedCallback = (success, data, ...callbackArgs) => {
          marketPlugin[pluginMethodName] = originalPluginMethod;
          if (!success) return callback(success, data, ...callbackArgs);
          const filteredItems = filterNamedItemsByChineseSearch(JSON.parse(data), originalSearch, nameFields);
          return callback(true, JSON.stringify(filteredItems), ...callbackArgs);
        };
        return originalPluginMethod(JSON.stringify(filters), wrappedCallback);
      };
      try {
        return originalRefresh(...args);
      } catch (error) {
        marketPlugin[pluginMethodName] = originalPluginMethod;
        throw error;
      }
    };
    app.__zhChineseSearchEnabled = true;
  }

  function waitForChineseWfmListSearch(attempt = 0) {
    enableChineseWfmListSearch("wfmOrdersApp", "GetWFMOrders", ["name"]);
    enableChineseWfmListSearch("wfmContractsApp", "GetWFMContracts", ["weaponName", "name"]);
    if (
      (!window.wfmOrdersApp?.__zhChineseSearchEnabled || !window.wfmContractsApp?.__zhChineseSearchEnabled) &&
      attempt < 40
    ) {
      setTimeout(() => waitForChineseWfmListSearch(attempt + 1), 250);
    }
  }

  function enableChineseUnveiledRivenSearch() {
    const app = window.unveiledRivensApp;
    const rivenPlugin = window.plugin?.get?.();
    if (!app?.refresh || !rivenPlugin?.GetFilteredUnveiledRivensInfo || app.__zhChineseSearchEnabled) return;

    const originalRefresh = app.refresh.bind(app);
    const originalGetFilteredRivens = rivenPlugin.GetFilteredUnveiledRivensInfo.bind(rivenPlugin);
    app.refresh = function (...args) {
      const originalSearch = this.selectedSearch || "";
      if (!hasChineseCharacters(originalSearch)) return originalRefresh(...args);

      rivenPlugin.GetFilteredUnveiledRivensInfo = function (filterSettings, callback) {
        const filters = JSON.parse(filterSettings);
        filters.search = "";
        const wrappedCallback = (success, data) => {
          rivenPlugin.GetFilteredUnveiledRivensInfo = originalGetFilteredRivens;
          if (!success) return callback(success, data);
          const filteredItems = filterNamedItemsByChineseSearch(JSON.parse(data), originalSearch, ["weaponName", "name"]);
          return callback(true, JSON.stringify(filteredItems));
        };
        return originalGetFilteredRivens(JSON.stringify(filters), wrappedCallback);
      };
      try {
        return originalRefresh(...args);
      } catch (error) {
        rivenPlugin.GetFilteredUnveiledRivensInfo = originalGetFilteredRivens;
        throw error;
      }
    };
    app.__zhChineseSearchEnabled = true;
  }

