  function enableChineseRivenFinderWeaponSearch() {
    const app = window.rivenFinderApp;
    const rivenPlugin = window.plugin?.get?.();
    if (!app?.refreshWeaponSearch || !rivenPlugin?.GetRivenWeapons || app.__zhChineseWeaponSearchEnabled) return;

    const originalGetRivenWeapons = rivenPlugin.GetRivenWeapons.bind(rivenPlugin);
    let allWeaponsPromise;
    const getAllWeapons = () => {
      if (!allWeaponsPromise) {
        allWeaponsPromise = new Promise(resolve => {
          originalGetRivenWeapons("", (success, data) => resolve(success ? JSON.parse(data) : []));
        });
      }
      return allWeaponsPromise;
    };
    const translateWeaponsForDisplay = weapons => weapons.map(weapon => ({
      ...weapon,
      name: translateDisplayOnlyItemName(weapon.name)
    }));
    const getDictionaryMatches = searchTerm => {
      const normalizedSearch = searchTerm.toLowerCase();
      return Object.entries(displayOnlyItemTranslations)
        .filter(([englishName, chineseName]) =>
          englishName.toLowerCase().includes(normalizedSearch) ||
          chineseName.toLowerCase().includes(normalizedSearch)
        )
        .map(([englishName]) => englishName)
        .slice(0, 50);
    };
    const getWeaponsByEnglishNames = englishNames => Promise.all(englishNames.map(englishName =>
      new Promise(resolve => originalGetRivenWeapons(englishName, (success, data) => {
        if (!success) return resolve([]);
        try {
          resolve(JSON.parse(data));
        } catch {
          resolve([]);
        }
      }))
    )).then(groups => {
      const seen = new Set();
      return groups.flat().filter(weapon => {
        const key = weapon.uniqueID || weapon.name;
        if (seen.has(key)) return false;
        seen.add(key);
        return true;
      });
    });

    app.refreshWeaponSearch = function () {
      const searchTerm = this.weaponSearchString?.trim() || "";
      if (!hasChineseCharacters(searchTerm)) {
        return originalGetRivenWeapons(searchTerm, (success, data) => {
          if (!success) {
            console.error("Failed to get riven weapons: " + data);
            return;
          }
          this.weaponSearchData = translateWeaponsForDisplay(JSON.parse(data));
        });
      }

      getAllWeapons().then(weapons => {
        const normalizedSearch = searchTerm.toLowerCase();
        const matchesSearch = weapon => {
          const englishName = weapon.name?.toLowerCase() || "";
          const chineseName = getChineseSearchableItemName(weapon.name || "");
          return englishName.includes(normalizedSearch) || chineseName.includes(normalizedSearch);
        };
        const cachedMatches = weapons.filter(matchesSearch);
        if (cachedMatches.length) {
          this.weaponSearchData = translateWeaponsForDisplay(cachedMatches);
          return;
        }

        // The plugin's empty query is sometimes incomplete. Resolve dictionary matches
        // through the original English-only API instead of sending Chinese to the plugin.
        getWeaponsByEnglishNames(getDictionaryMatches(searchTerm)).then(foundWeapons => {
          this.weaponSearchData = translateWeaponsForDisplay(foundWeapons.filter(matchesSearch));
        });
      });
    };
    app.__zhChineseWeaponSearchEnabled = true;
  }

  function waitForChineseRivenFinderWeaponSearch(attempt = 0) {
    enableChineseRivenFinderWeaponSearch();
    if (!window.rivenFinderApp?.__zhChineseWeaponSearchEnabled && attempt < 40) {
      setTimeout(() => waitForChineseRivenFinderWeaponSearch(attempt + 1), 250);
    }
  }

  function getChineseMarketSearchSuggestions(searchTerm) {
    const normalizedSearch = searchTerm.trim().toLowerCase();
    if (!normalizedSearch) return [];

    return Object.entries(displayOnlyItemTranslations)
      .filter(([englishName, chineseName]) =>
        chineseName.toLowerCase().includes(normalizedSearch) || englishName.toLowerCase().includes(normalizedSearch)
      )
      .sort(([leftEnglish, leftChinese], [rightEnglish, rightChinese]) => {
        const leftRank = leftChinese.toLowerCase() === normalizedSearch ? 0 : leftChinese.toLowerCase().startsWith(normalizedSearch) ? 1 : 2;
        const rightRank = rightChinese.toLowerCase() === normalizedSearch ? 0 : rightChinese.toLowerCase().startsWith(normalizedSearch) ? 1 : 2;
        return leftRank - rightRank || leftChinese.length - rightChinese.length || leftEnglish.localeCompare(rightEnglish);
      })
      .slice(0, 50)
      .map(([englishName, chineseName]) => ({
        name: chineseName,
        urlName: chineseMarketSuggestionPrefix + encodeURIComponent(englishName),
        picture: ""
      }));
  }

  function selectChineseMarketSuggestion(englishName, originalSuggestionClicked) {
    const marketPlugin = window.plugin?.get?.();
    if (!marketPlugin?.GetWFMarketSearchSuggestions) return;

    marketPlugin.GetWFMarketSearchSuggestions(englishName, (success, response) => {
      if (!success) {
        console.warn("[AlecaFrame 中文补丁] 无法获取市场英文项目：", response);
        return;
      }
      const suggestions = JSON.parse(response);
      const normalizedName = englishName.toLowerCase();
      const suggestion = suggestions.find(item => item.name?.toLowerCase() === normalizedName) || suggestions[0];
      if (suggestion) originalSuggestionClicked(suggestion.name, suggestion.urlName);
    });
  }

  function enableChineseMarketSearch() {
    const app = window.buySellPanelApp;
    if (!app?.updateSearchSuggestions || !app?.suggestionClicked || app.__zhChineseMarketSearchEnabled) return;

    const originalUpdateSearchSuggestions = app.updateSearchSuggestions.bind(app);
    const originalSuggestionClicked = app.suggestionClicked.bind(app);
    app.updateSearchSuggestions = function () {
      const searchTerm = this.wfmSearchCurrentGuess || "";
      if (!hasChineseCharacters(searchTerm)) return originalUpdateSearchSuggestions();
      this.searchSuggestions = getChineseMarketSearchSuggestions(searchTerm);
      this.doingSearch = true;
      // In 3.x a stale English request may still be pending while Chinese
      // suggestions are produced locally. Invalidate it and clear its state.
      clearTimeout(this.searchTimer);
      if (typeof this.searchRequestId === "number") this.searchRequestId++;
      this.searching = false;
      this.searchError = false;
      this.activeSuggestion = -1;
    };
    app.suggestionClicked = function (itemName, itemUrlName) {
      if (!itemUrlName?.startsWith(chineseMarketSuggestionPrefix)) {
        return originalSuggestionClicked(itemName, itemUrlName);
      }
      const englishName = decodeURIComponent(itemUrlName.slice(chineseMarketSuggestionPrefix.length));
      selectChineseMarketSuggestion(englishName, originalSuggestionClicked);
    };
    app.__zhChineseMarketSearchEnabled = true;
  }

  function waitForChineseMarketSearch(attempt = 0) {
    enableChineseMarketSearch();
    if (!window.buySellPanelApp?.__zhChineseMarketSearchEnabled && attempt < 40) {
      setTimeout(() => waitForChineseMarketSearch(attempt + 1), 250);
    }
  }

  function translateString(value) {
    if (!value || !/[A-Za-z]/.test(value)) return value;
    // Vue must compile its original expressions and string literals unchanged.
    // Translate the resulting DOM text after mount instead.
    if (value.includes("{{") || value.includes("}}")) return value;
    const leading = value.match(/^\s*/)?.[0] ?? "";
    const trailing = value.match(/\s*$/)?.[0] ?? "";
    const core = value.slice(leading.length, value.length - trailing.length);
    if (!core || translatedValues.has(core)) return value;
    let translated = translations[core] || translations[core.replace(/\s+/g, " ")] || getDisplayOnlyItemTranslation(core);
    if (!translated) {
      for (const [pattern, replacement] of dynamicRules) {
        if (pattern.test(core)) {
          translated = core.replace(pattern, replacement);
          break;
        }
      }
    }
    if (!translated) {
      translated = translateCompoundText(core);
    }
    if (!translated) {
      const labeledLocation = core.match(/^([A-Za-z][A-Za-z .'-]+)(\s+\(.+\).*)$/);
      if (labeledLocation && translations[labeledLocation[1]]) {
        translated = translations[labeledLocation[1]] + labeledLocation[2];
      }
    }
    return translated ? leading + translated + trailing : value;
  }

  function translateCompoundText(core) {
    const relicQualityMatch = core.match(/^(Lith|Meso|Neo|Axi) ([A-Z]\d+) (Intact|Exceptional|Flawless|Radiant)$/i);
    if (relicQualityMatch) {
      const eraName = relicQualityMatch[1][0].toUpperCase() + relicQualityMatch[1].slice(1).toLowerCase();
      const qualityName = relicQualityMatch[3][0].toUpperCase() + relicQualityMatch[3].slice(1).toLowerCase();
      const era = translations[eraName] || getDisplayOnlyItemTranslation(eraName);
      const quality = translations[qualityName] || getDisplayOnlyItemTranslation(qualityName);
      return era && quality ? `${era} ${relicQualityMatch[2]} ${quality}` : null;
    }

    const relicMatch = core.match(/^(Lith|Meso|Neo|Axi) ([A-Z]\d+) Relic$/i);
    if (relicMatch) {
      const era = translations[relicMatch[1][0].toUpperCase() + relicMatch[1].slice(1).toLowerCase()];
      return era ? `${era} ${relicMatch[2]} 遗物` : null;
    }

    const relicNameMatch = core.match(/^(Lith|Meso|Neo|Axi) ([A-Z]\d+)$/i);
    if (relicNameMatch) {
      const era = translations[relicNameMatch[1][0].toUpperCase() + relicNameMatch[1].slice(1).toLowerCase()];
      return era ? `${era} ${relicNameMatch[2]}` : null;
    }

    const part = Object.keys(compoundPartTranslations).find(candidate => core.endsWith(` ${candidate}`));
    if (!part) return null;
    const itemName = core.slice(0, -(part.length + 1));
    const baseTranslation = getCompoundBaseTranslation(itemName);
    return baseTranslation ? `${baseTranslation} ${compoundPartTranslations[part]}` : null;
  }

  function getCompoundBaseTranslation(itemName) {
    const directTranslation = getDisplayOnlyItemTranslation(itemName) || translations[itemName];
    if (directTranslation) return directTranslation;

    const primeMatch = itemName.match(/^(.*) Prime$/);
    if (!primeMatch) return null;
    const baseTranslation = getDisplayOnlyItemTranslation(primeMatch[1]) || translations[primeMatch[1]];
    return baseTranslation ? `${baseTranslation} Prime` : null;
  }

  function translateElement(element, includeMarket = false) {
    if (!(element instanceof Element)) return;
    if (element.closest(playerIdentitySelector)) return;
    if (!includeMarket && isMarketPanelElement(element)) return;
    for (const attribute of ["placeholder", "title", "alt", "aria-label"]) {
      if (element.hasAttribute(attribute)) {
        const current = element.getAttribute(attribute);
        const translated = translateString(current);
        if (translated !== current) element.setAttribute(attribute, translated);
      }
    }
  }

  // Vue replaces timer text after the initial document translation.
  function translateTimerStatuses() {
    const stateLabels = {
      DAY: "白天",
      NIGHT: "夜晚",
      COLD: "寒冷",
      WARM: "温暖",
      FASS: "法斯",
      VOME: "沃姆"
    };

    const timerCards = ["earthTimer", "cetusTimer", "vallisTimer", "cambionTimer"];
    for (const timerCard of timerCards) {
      const card = document.getElementById(timerCard);
      if (!card) continue;

      for (const label of card.getElementsByClassName("timerStatus")) {
        const current = label.textContent?.trim();
        const translated = stateLabels[current];
        if (translated && label.textContent !== translated) label.textContent = translated;
      }
    }
  }

  function translateRivenTraitText(value) {
    if (!value || !/[A-Za-z]/.test(value)) return value;
    if (value.includes("{{") || value.includes("}}")) return value;
    let translated = value;
    for (const [english, chinese] of rivenTraitTranslations) translated = translated.replaceAll(english, chinese);
    return translated;
  }

  function translateRivenTraitNode(node) {
    if (node.nodeType !== Node.TEXT_NODE || !node.parentElement) return;
    if (!node.parentElement.closest(".rivenTrait, .rivenDetailsStatText, .similarRivenAttr, .goodAttrMandatory, .goodAttrOptional, .badAttrItem, .attrName, .rivenFinderAttrSelectAttr option")) return;
    const translated = translateRivenTraitText(node.nodeValue);
    if (translated !== node.nodeValue) node.nodeValue = translated;
  }

  function translateRivenChartLabels(attempt = 0) {
    const chart = window.rivenPlatinumChart;
    if (!chart?.data?.datasets) {
      if (attempt < 40) setTimeout(() => translateRivenChartLabels(attempt + 1), 250);
      return;
    }
    let changed = false;
    for (const dataset of chart.data.datasets) {
      const translated = translateString(dataset?.label);
      if (translated && translated !== dataset.label) {
        dataset.label = translated;
        changed = true;
      }
    }
    if (changed) chart.update("none");
  }

  function translateArbitrationChartText(value) {
    if (Array.isArray(value)) return value.map(translateArbitrationChartText);
    if (typeof value !== "string") return value;
    let translated = translateString(value);
    const metric = translated.match(/^(.+?):\s*(.+)$/);
    if (metric) translated = `${translateString(metric[1])}: ${metric[2]}`;
    translated = translated.replace(/\b(spawns\/min|spawns|agents)\b/g, unit => translations[unit] || unit);
    return translated;
  }

  function installArbitrationChartTranslations(attempt = 0) {
    const Chart = window.Chart;
    if (!Chart?.register) {
      if (attempt < 40) setTimeout(() => installArbitrationChartTranslations(attempt + 1), 250);
      return;
    }
    if (Chart.__zhArbitrationLabelsInstalled) return;
    Chart.register({
      id: "alecaframeZhArbitrationLabels",
      beforeUpdate(chart) {
        if (!chart.canvas?.closest?.(".arbRunChart")) return;
        for (const dataset of chart.data?.datasets || []) {
          if (typeof dataset.label === "string") dataset.label = translateString(dataset.label);
        }
        for (const axis of Object.values(chart.options?.scales || {})) {
          if (typeof axis.title?.text === "string") axis.title.text = translateString(axis.title.text);
        }
        const callbacks = chart.options?.plugins?.tooltip?.callbacks;
        if (!callbacks) return;
        for (const name of ["title", "label"]) {
          const original = callbacks[name];
          if (typeof original !== "function" || original.__zhArbitrationLabel) continue;
          const translated = function (...args) {
            return translateArbitrationChartText(original.apply(this, args));
          };
          translated.__zhArbitrationLabel = true;
          callbacks[name] = translated;
        }
      }
    });
    Chart.__zhArbitrationLabelsInstalled = true;
    for (const chart of Object.values(Chart.instances || {})) {
      if (chart.canvas?.closest?.(".arbRunChart")) chart.update("none");
    }
  }

  function translateRivenChallengeText(value) {
    if (!value || value.includes("{{") || value.includes("}}")) return value;
    const directTranslations = {
      "Kill Enemies while Sliding": "滑行时击杀敌人",
      "Zaw Riven": "Zaw 裂罅",
      "Kitgun Riven": "组合枪裂罅",
      "Melee Riven": "近战裂罅",
      "Rifle Riven": "步枪裂罅",
      "Shotgun Riven": "霰弹枪裂罅",
      "Pistol Riven": "手枪裂罅",
      "Archgun Riven": "Archwing 枪械裂罅"
    };
    const trimmed = value.trim();
    if (directTranslations[trimmed]) return value.replace(trimmed, directTranslations[trimmed]);

    let match = trimmed.match(/^Kill (\d+) Enemies while Sliding with an equipped Dragon Key equipped$/i);
    if (match) return `装备龙钥匙时滑行击杀 ${match[1]} 名敌人`;
    match = trimmed.match(/^Complete a Survival mission with level (\d+) or higher enemies without killing anyone$/i);
    if (match) return `在不击杀任何敌人的情况下完成一场敌人等级不低于 ${match[1]} 的生存任务`;
    match = trimmed.match(/^Kill (\d+) unalerted Tusk Ballistas with a Headshot in one day$/i);
    if (match) return `在一天内用爆头击杀 ${match[1]} 名未警觉的巨牙重炮手`;
    if (/^Kill unalerted Tusk Ballistas with a Headshot$/i.test(trimmed)) return "用爆头击杀未警觉的巨牙重炮手";
    match = trimmed.match(/^Complete a Defense mission with level (\d+) or higher enemies with the defense objective taking no damage$/i);
    if (match) return `完成一场敌人等级不低于 ${match[1]} 且防御目标未受伤害的防御任务`;
    return value;
  }

  function translateRivenChallengeNode(node) {
    if (node.nodeType !== Node.TEXT_NODE || !node.parentElement) return;
    if (!node.parentElement.closest(".itemGroupName, .veiledRivenName, .veiledRivenChallenge")) return;
    const translated = translateRivenChallengeText(node.nodeValue);
    if (translated !== node.nodeValue) node.nodeValue = translated;
  }

  function translateMarketPanel(root) {
    const panel = root instanceof Element
      ? root.closest(marketPanelSelector) || (root.matches(marketPanelSelector) ? root : null)
      : document.querySelector(marketPanelSelector);
    if (!panel) return;

    for (const input of panel.querySelectorAll('input[placeholder="Search"]')) input.setAttribute("placeholder", "搜索");
    addMarketItemLabelTranslation(panel);
    addMarketSuggestionTranslation(panel);
    addMarketOrderTitleTranslations(panel);
    translateMarketOwnedLabels(panel);
    for (const label of panel.querySelectorAll('.quoteSelectedItem > strong, .quoteComposerItem, .quoteSuggestion > span, .marketIdentityText > h3, .marketWeapon')) {
      const englishName = label.textContent?.trim();
      if (!englishName || englishName.includes("{{")) continue;
      const chineseName = translateDisplayOnlyItemName(englishName);
      if (chineseName && chineseName !== englishName) label.dataset.zhMarketDisplayName = chineseName;
      else delete label.dataset.zhMarketDisplayName;
    }
    const walker = document.createTreeWalker(panel, NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT);
    let node;
    while ((node = walker.nextNode())) {
      if (node.nodeType === Node.ELEMENT_NODE) {
        translateElement(node, true);
        continue;
      }
      if (node.parentElement?.closest(marketItemNameSelector + ', ' + playerIdentitySelector + ', script, style, noscript, code, pre, textarea')) continue;
      const translated = translateString(node.nodeValue);
      if (translated !== node.nodeValue) node.nodeValue = translated;
    }
  }

  function translateAllMarketPanels() {
    for (const panel of document.querySelectorAll(marketPanelSelector)) translateMarketPanel(panel);
  }

  function addMarketItemLabelTranslation(panel) {
    for (const label of panel.querySelectorAll(".wfmRightItemName")) {
      const englishName = label.textContent?.trim();
      const chineseName = translateDisplayOnlyItemName(englishName);
      if (!chineseName || chineseName === englishName) {
        delete label.dataset.zhMarketItemLabel;
        continue;
      }
      label.dataset.zhMarketItemLabel = chineseName;
    }
  }

  function addMarketSuggestionTranslation(panel) {
    for (const label of panel.querySelectorAll(".wfmGuessesHolder span")) {
      const englishName = label.textContent?.trim();
      const chineseName = translateDisplayOnlyItemName(englishName);
      if (!chineseName || chineseName === englishName) {
        delete label.dataset.zhMarketSuggestionLabel;
        continue;
      }
      label.dataset.zhMarketSuggestionLabel = chineseName;
    }
  }

  function addMarketOrderTitleTranslations(panel) {
    const isVueOrderList = panel.id === "MyOrdersTab" || panel.id === "MyContractsTab";
    for (const label of panel.querySelectorAll('.wfmItemName')) {
      const englishName = label.dataset.zhMarketOrderEnglish || label.textContent?.trim();
      const chineseName = translateDisplayOnlyItemName(englishName);
      if (!englishName || !chineseName || chineseName === englishName) continue;

      // Vue owns the names in My Orders / My Contracts. Keep its original text
      // node intact and expose the Chinese line through CSS, otherwise a future
      // Vue refresh can fail to reconcile the card and hide returned orders.
      if (isVueOrderList) {
        label.dataset.zhMarketOrderEnglish = englishName;
        label.dataset.zhMarketOrderChinese = chineseName;
        continue;
      }

      if (label.dataset.zhMarketOrderEnglish !== englishName) {
        label.dataset.zhMarketOrderEnglish = englishName;
        label.replaceChildren();

        const chineseLine = document.createElement('span');
        chineseLine.className = 'zh-market-order-name-cn';
        const englishLine = document.createElement('span');
        englishLine.className = 'zh-market-order-name-en';
        label.append(chineseLine, englishLine);
      }

      const chineseLine = label.querySelector('.zh-market-order-name-cn');
      const englishLine = label.querySelector('.zh-market-order-name-en');
      if (chineseLine) chineseLine.textContent = chineseName;
      if (englishLine) englishLine.textContent = englishName;
    }
  }

  function translateMarketOwnedLabels(panel) {
    for (const label of panel.querySelectorAll('.wfmItemOwnedText')) {
      const match = label.textContent?.trim().match(/^(\d+)\s+owned$/i);
      if (match) label.textContent = `${match[1]} 拥有`;
    }
  }

  function translateFoundryDetails() {
    // This dialog is owned by Vue. Writing textContent into its component rows
    // can remove Vue-managed text nodes while a new detail response is being
    // rendered, leaving a new model beside components from the previous item.
    // Keep this path native until it exposes a display-only translation hook.
    return;

    const modal = document.getElementById("modalFroundryDetails");
    if (!modal || modal.offsetParent === null) return;

    for (const title of modal.querySelectorAll(".foundryDetailsTopTopTitle")) {
      const translated = translateString(title.textContent);
      if (translated !== title.textContent) title.textContent = translated;
    }

    for (const textElement of modal.querySelectorAll(".foundryDetailsTopDescription, .foundryDetailsCustomWarframePassive .passive")) {
      const translated = translateString(textElement.textContent);
      if (translated !== textElement.textContent) textElement.textContent = translated;
    }

    const translateFoundryItemName = (value) => {
      const translated = translateString(value);
      if (translated !== value) return translated;
      const part = Object.keys(compoundPartTranslations).find(candidate => value.endsWith(` ${candidate}`));
      if (!part) return value;
      const itemName = value.slice(0, -(part.length + 1));
      return `${itemName} ${compoundPartTranslations[part]}`;
    };

    for (const component of modal.querySelectorAll(".foundryDetailsComponentName")) {
      const current = component.textContent;
      const match = current.match(/^(.*?)(\s*\(\d+\/\d+\))?$/);
      const translated = translateFoundryItemName(match?.[1] ?? current);
      if (translated !== (match?.[1] ?? current)) component.textContent = translated + (match?.[2] ?? "");
    }

    for (const ability of modal.querySelectorAll(".foundryDetailsCustomWarframeAbilityItem")) {
      const current = ability.textContent;
      const match = current.match(/^(\d+\)\s*)(.+)$/);
      if (!match) continue;
      const translated = translateString(match[2]);
      if (translated !== match[2]) ability.textContent = match[1] + translated;
    }

    // These words are weapon-mode values, not general UI labels. Keeping them
    // scoped to the details modal avoids changing unrelated controls elsewhere.
    const weaponDetailValues = {
      "Auto": "自动",
      "Burst": "连发",
      "Radial Attack": "范围攻击",
      "Alarming": "警报"
    };
    for (const element of modal.querySelectorAll(".triggerType, .noiseType, .foundryDetailsWeaponShootModesHeader .foundryDetailsComponentName, .foundryDetailsWeaponShootModesBody .shotType .foundryDetailsCustomGeneralEntryValue")) {
      const translated = weaponDetailValues[element.textContent.trim()];
      if (translated) element.textContent = translated;
    }

    for (const element of modal.querySelectorAll("[data-tippy-content]")) {
      const current = element.getAttribute("data-tippy-content");
      const translated = translateString(current);
      if (translated !== current) element.setAttribute("data-tippy-content", translated);
    }
  }

  function toHuijiWikiUrl(value) {
    if (typeof value !== "string") return null;
    if (value.startsWith("https://warframe.fandom.com")) {
      return value.replace("https://warframe.fandom.com", "https://warframe.huijiwiki.com");
    }
    if (value.startsWith("https://wiki.warframe.com/w/")) {
      return value.replace("https://wiki.warframe.com/w/", "https://warframe.huijiwiki.com/wiki/");
    }
    return null;
  }

  function installHuijiWikiRedirect() {
    document.addEventListener("click", (event) => {
      const link = event.target instanceof Element ? event.target.closest("a[href]") : null;
      const redirected = toHuijiWikiUrl(link?.href);
      if (!redirected) return;
      event.preventDefault();
      event.stopImmediatePropagation();
      window.overwolf?.utils?.openUrlInDefaultBrowser?.(redirected);
    }, { capture: true });
  }

  function translateTree(root) {
    if (!root) return;
    const element = root.nodeType === Node.ELEMENT_NODE ? root : root.parentElement;
    if (element?.closest?.("#modalFroundryDetails")) return;
    if (root.nodeType === Node.TEXT_NODE) {
      const parent = root.parentElement;
      if (!parent) return;
      if (parent.closest(playerIdentitySelector)) return;
      if (isMarketPanelElement(parent)) {
        translateMarketPanel(parent);
        return;
      }
      if (isDisplayOnlyItemName(parent) || /^(SCRIPT|STYLE|NOSCRIPT|CODE|PRE|TEXTAREA)$/i.test(parent.tagName)) return;
      translateRivenTraitNode(root);
      const translated = translateString(root.nodeValue);
      if (translated !== root.nodeValue) root.nodeValue = translated;
      translateRivenChallengeNode(root);
      return;
    }
    if (root.nodeType !== Node.ELEMENT_NODE && root.nodeType !== Node.DOCUMENT_NODE && root.nodeType !== Node.DOCUMENT_FRAGMENT_NODE) return;
    if (root.nodeType === Node.ELEMENT_NODE && isMarketPanelElement(root)) {
      translateMarketPanel(root);
      return;
    }
    addDisplayOnlyItemTranslations(root);
    if (root.nodeType === Node.ELEMENT_NODE) translateElement(root);
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT);
    let node;
    while ((node = walker.nextNode())) {
      if (node.nodeType === Node.TEXT_NODE) {
        const parent = node.parentElement;
        if (!parent || parent.closest(playerIdentitySelector) || isMarketPanelElement(parent) || isDisplayOnlyItemName(parent) || /^(SCRIPT|STYLE|NOSCRIPT|CODE|PRE|TEXTAREA)$/i.test(parent.tagName)) continue;
        translateRivenTraitNode(node);
        const translated = translateString(node.nodeValue);
        if (translated !== node.nodeValue) node.nodeValue = translated;
        translateRivenChallengeNode(node);
      } else {
        translateElement(node);
      }
    }
  }

